import{z as s,x as B,o as t,c as p,q as r,j as A,D as E,d as o,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"厂级数据闭环","description":"","frontmatter":{"title":"厂级数据闭环","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fab-data-loop.md","filePath":"litho/fab-data-loop.md","lastUpdated":1791063341000}'),C={name:"litho/fab-data-loop.md"};function d(D,a,F,h,P,m){const l=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="厂级数据闭环" tabindex="-1">厂级数据闭环 <a class="header-anchor" href="#厂级数据闭环" aria-label="Permalink to &quot;厂级数据闭环&quot;">​</a></h1><div class="epigraph"><p>闭环的带宽由数据能不能按时、按键、按版本到达执行器决定；算法再好，也对不上错层、过期、未匹配的数。</p><footer>—— 对照 SEMI 工厂数据与 APC 接口通称；晶圆厂 MES / FDC 与光刻控制的公开架构</footer></div><p><a href="/litho/tool-to-tool-overlay">上一课</a>要求按机台对存指纹。缺口是系统：计量、扫描机、轨道、刻蚀、MES 如何把 ton 级数据收成可用状态。本课钉厂级数据闭环。虚拟计量如何在缺测时充数，留给<a href="/litho/virtual-metrology">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据闭环：晶圆 id、层、食谱、机台、卡盘、OPC 版本、计量机、时间戳，必须能 join。FDC（故障检测）吃传感器，APC 吃计量，SPC 吃残差，分派吃规格。缺公共键，现场只能做单机小闭环， holistic 停留在幻灯片。延迟：套刻结果晚于下一批已曝光，反馈环开路。</p><p>缺口是<strong>合同与延迟</strong>，不是买一套大数据平台。版本：模型与校正项集必须随数据走，否则用新核解释旧热点。</p><p><span class="marginnote">MES（制造执行系统）就是工厂的「总账本兼调度员」：每片晶圆是谁、走到哪一层、用过哪台机器、下过什么食谱，全记在它名下。所谓数据闭环，第一步就是让每条测量数据都能挂回这本账——挂不回去的数，量得再准也是废纸。</span></p><h3 id="fdc-不是-apc" tabindex="-1">FDC 不是 APC <a class="header-anchor" href="#fdc-不是-apc" aria-label="Permalink to &quot;FDC 不是 APC&quot;">​</a></h3><p>振动、激光气体、RF 反射报警的是设备健康，应抑制 APC 或扣留，而不是把振动当 CD 去补剂量。两类系统要握手：FDC 红则 APC 停。</p><p><span class="marginnote">SEMI E133 等描述 APC 系统接口。本课用其精神：数据质量位、限幅、审计，不背诵条款号当内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构：采集 → 上下文对齐 → 质量过滤 → 分发给 APC/SPC/FDC/良率。审计：谁改了剂量偏置。与重工：状态位。与设计：热点坐标回写 LFD 库要走变更控制，不能让产线热点自动改库。安全：配方下载权限。</p><p>延迟预算要按环写：套刻反馈允许晚一批，CD 前馈（胶厚）必须在曝光前到达。对不齐的数据宁可不补，也不要补错层。这是 SEMI APC 接口强调质量位的原因。</p><p><span class="marginnote">延迟账可以具体化：假设量测排队 30 分钟、对齐 5 分钟、配方下发 10 分钟，闭环响应就接近 45 分钟；若产线一小时出三批，反馈注定赶不上下一批，只能做成跨批的慢环。环的快慢是设计出来的，不是号称出来的。</span></p>',14)),(t(),A(n,null,{default:E(()=>[i(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E8%AE%A1%E9%87%8F%E7%BB%93%E6%9E%9C%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20J%7B%22join%20%E9%94%AE%E5%AF%B9%E5%BE%97%E4%B8%8A%3F%22%7D%0A%20%20J%20--%3E%7C%E9%94%99%E5%B1%82%E6%88%96%E8%BF%87%E6%9C%9F%7C%20BAD%5B%22%E5%AE%81%E5%8F%AF%E4%B8%8D%E8%A1%A5%2C%20%E9%98%B2%E5%A2%9E%E7%9B%8A%E5%8F%8D%E5%8F%B7%22%5D%0A%20%20J%20--%3E%7C%E5%AF%B9%E9%BD%90%7C%20L%7B%22%E8%B5%B6%E5%BE%97%E4%B8%8A%E4%BD%BF%E7%94%A8%E7%82%B9%3F%22%7D%0A%20%20L%20--%3E%7C%E6%9B%9D%E5%85%89%E5%89%8D%7C%20FF%5B%22%E5%89%8D%E9%A6%88%E5%8F%AF%E7%94%A8%20(%E5%A6%82%E8%83%B6%E5%8E%9A)%22%5D%0A%20%20L%20--%3E%7C%E6%99%9A%E4%B8%80%E6%89%B9%7C%20FB%5B%22%E5%8F%AA%E5%81%9A%E5%A5%97%E5%88%BB%E7%B1%BB%E8%B7%A8%E6%89%B9%E5%8F%8D%E9%A6%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"这张图回答的是：一条反馈何时可用、何时必须闭嘴——先验上下文，再验到达时间，两关都过才允许动配方。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"闭环有效带宽 \\(\\approx\\) 1 /（计量周期 + 对齐 + 队列）。上下文错误等价于增益反号。数据质量位（对焦失败、SEM 充电）必须进滤波器，否则 EWMA 被野点拉跑——匹配与 SPC 课的操作化。",-1)),(t(),A(n,null,{default:E(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%20%E8%BD%A8%E9%81%93%20%E5%88%BB%E8%9A%80%20%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20CTX%5B%22%E6%99%B6%E5%9C%86-%E5%B1%82-%E7%89%88%E6%9C%AC%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CTX%20--%3E%20Q%5B%22%E8%B4%A8%E9%87%8F%E4%BD%8D%E8%BF%87%E6%BB%A4%22%5D%0A%20%20Q%20--%3E%20APC%5B%22APC%20%2F%20SPC%20%2F%20FDC%22%5D%0A%20%20FDC%5B%22%E8%AE%BE%E5%A4%87%E5%81%A5%E5%BA%B7%22%5D%20--%3E%20GATE%5B%22%E5%85%81%E8%AE%B8%E8%A1%A5%E5%81%BF%3F%22%5D%0A%20%20GATE%20--%3E%20APC%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>对齐失败等价于增益反号。FDC 红应关掉 APC，避免把振动当 CD 去补剂量。</p><p><span class="marginnote">初学者容易以为闭环越勤快越好。上下文错一条——补错层、用过期版本——等价于把修正方向反过来，越勤快错得越快。所以质量位不过关时，正确动作不是「先补着」，而是明确的不补并留下审计记录。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写具体商业 MES 商标当物理定律。不进入大模型训练栈。网络安全只点名权限。</p><p>后课默认：闭环有上下文键、质量位和 FDC 门。下一课在计量稀疏处用虚拟计量，仍受同一质量合同约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>厂级闭环靠 join 键、延迟和质量位，而不是靠算法名称。</li><li>FDC 健康门应能关掉 APC。</li><li>模型版本随数据走。</li><li>出处：SEMI APC/工厂数据接口通称；FDC–APC 分工的产线架构。</li></ul>',7))])}const u=s(C,[["render",d]]);export{c as __pageData,u as default};
